/*-- Reset CSS --*/ #google_translate_element { clear: both; } a,abbr,acronym,address,applet,b,big,blockquote,body,caption,center,cite,code,dd,del,dfn,div,dl,dt,em,fieldset,font,form,h1,h2,h3,h4,h5,h6,html,i,iframe,img,ins,kbd,label,legend,li,object,p,pre,q,s,samp,small,span,strike,strong,sub,sup,table,tbody,td,tfoot,th,thead,tr,tt,u,ul,var{ padding:0; margin:0; border:0; outline:none; vertical-align:baseline; background:0 0; text-decoration:none } dl,ul{ list-style-position:inside; list-style:none } ul li{ list-style:none } caption{ text-align:center } img{ border:none; position:relative } a,a:visited{ text-decoration:none } .clearfix{ clear:both } .section,.widget,.widget ul{ margin:0; padding:0 } a{ color:var(--main-color) } a img{ border:0 } abbr{ text-decoration:none } .CSS_LIGHTBOX{ z-index:999999!important } .CSS_LIGHTBOX_ATTRIBUTION_INDEX_CONTAINER .CSS_HCONT_CHILDREN_HOLDER > .CSS_LAYOUT_COMPONENT.CSS_HCONT_CHILD:first-child > .CSS_LAYOUT_COMPONENT{ opacity:0 } .separator a{ text-decoration:none!important; clear:none!important; float:none!important; margin-left:0!important; margin-right:0!important } #Navbar1,#navbar-iframe,.widget-item-control,a.quickedit,.home-link,.feed-links{ display:none!important } .center{ display:table; margin:0 auto; position:relative } .widget > h2,.widget > h3{ display:none } .widget iframe,.widget img{ max-width:100% } button,input,select,textarea{ font-family:var(--body-font); -webkit-appearance:none; -moz-appearance:none; appearance:none; outline:none; border-radius:0 } /*-- Style CSS --*/ *{ box-sizing:border-box } html{ position:relative; word-break:break-word; word-wrap:break-word; text-rendering:optimizeLegibility; -webkit-font-smoothing:antialiased; -webkit-text-size-adjust:100% } body{ position:relative; background:var(--body-bg); background-color:var(--body-bg-color); font-family:var(--body-font); font-size:14px; color:var(--text-color); font-weight:400; font-style:normal; line-height:1.4em } .rtl{ direction:rtl } h1,h2,h3,h4,h5,h6{ font-family:var(--title-font); font-weight:700 } a,input,button{ transition:all .0s ease }
#page-loader{ position:fixed; top:0; left:0; width:100%; height:100%; background:#ffffff; display:flex; align-items:center; justify-content:center; z-index:9999; }
.spinner{ width:50px; height:50px; border:5px solid #e0e0e0; border-top:5px solid #2196f3; border-radius:50%; animation:spin 1s linear infinite; }
@keyframes spin{ 0%{transform:rotate(0deg);} 100%{transform:rotate(360deg);} }
#outer-wrapper{ position:relative; overflow:hidden; width:100%; max-width:100%; background-color:var(--outer-bg); margin:0 auto; padding:0 } .is-boxed #outer-wrapper{ width:$(row.width + 50px); max-width:100%; box-shadow:0 0 20px rgba(0,0,0,0.1) } .is-dark .is-boxed #outer-wrapper{ box-shadow:0 0 20px rgba(0,0,0,0.3) } .container{ position:relative } .row-x1{ width:$(row.width) } .row-x2{ width:100% } .flex-center{ display:flex; justify-content:center } #content-wrapper{ position:relative; float:left; width:100%; overflow:hidden; padding: 0px 0px 30px; margin:0 } #content-wrapper > .container{ display:flex; justify-content:space-between } .is-left #content-wrapper > .container,.rtl .is-right #content-wrapper > .container{ flex-direction:row-reverse } .rtl .is-left #content-wrapper > .container{ flex-direction:row } .theiaStickySidebar:before,.theiaStickySidebar:after{ content:''; display:table; clear:both } #main-wrapper{ position:relative; width:$(mainpost.width) }
#main-wrapper .title-wrap{display:none}
.no-sidebar #main-wrapper{ width:100% } #sidebar-wrapper{ position:relative; width:$(sidebar.width) }
.templateify-ads-side { display: block; background-color: #eee; text-align: center; font-size: 13px; color: #aaaaaa; font-weight: 400; font-style: italic; line-height: 250px; border: 1px solid #ccc; }
#sidebar-wrappers{ position:relative; width:$(sidebars.width) } .no-sidebar #sidebar-wrapper{ display:none } .no-sidebar #sidebar-wrappers{ display:none } .footer-logo img { filter: invert(1); } .btn{ position:relative; border:0; border-radius:var(--border-radius) } .entry-image-wrap,.author-avatar-wrap,.comments .avatar-image-container{ display:block; position:relative; overflow:hidden; background-color:rgba(155,155,155,0.05); z-index:5; color:transparent!important } .entry-thumb,.author-avatar{ border-radius:0px; display:block; position:relative; width:100%; height:100%; background-size:cover; background-position:center center; background-repeat:no-repeat; z-index:1; opacity:0; transition:opacity .35s ease,filter 0s ease } .author-avatar{ background-size:100%; background-position:0 0 } .entry-thumb.lazy-ify,.author-avatar.lazy-ify{ opacity:1 } .entry-image-wrap:hover .entry-thumb,.card-style:hover .entry-image-wrap .entry-thumb{ filter:brightness(1.03) } .entry-image-wrap.is-video:after{ position:absolute; content:'\f04b'; top:50%; right:50%; background-color:rgba(0,0,0,0.5); width:34px; height:34px; font-family:'Font Awesome 5 Free'; font-size:11px; color:#fff; font-weight:900; display:flex; align-items:center; justify-content:center; z-index:5; transform:translate(50%,-50%); box-sizing:border-box; padding:0 0 0 1px; margin:0; border:2px solid #fff; border-radius:50%; opacity:.9; transition:opacity .17s ease } .entry-image-wrap.is-video:hover:after,.card-style:hover .entry-image-wrap.is-video:after{ opacity:1 } .card-style .entry-image-wrap.is-video:after{ top:15px; right:15px; transform:translate(0) } .rtl .card-style .entry-image-wrap.is-video:after{ left:15px; right:unset } .entry-category{ position:absolute; padding: 2px 8px; background-color: var(--button-bg); left: 16px; z-index: 10; top: 15px; display:block; font-size:13px; color:#fff; font-weight:500; text-transform:capitalize; margin:0 0 5px } .entry-title{ display:block; color:var(--post-title-color); font-weight:500; line-height:1.3em } .entry-title a{ display:block; color:var(--post-title-color) } .entry-title a:hover{ color:var(--post-title-hover-color) } .entry-meta{ display:flex; font-family:var(--meta-font); font-size:12px; color:var(--meta-color); font-weight:400; margin:4px 0 0 } .entry-meta .mi{ display:flex } .entry-meta .mi,.entry-meta .sp{ margin:0 4px 0 0 } .rtl .entry-meta .mi,.rtl .entry-meta .sp{ margin:0 0 0 4px } .entry-meta .author-name{ color:var(--main-color); font-weight:500 } .excerpt{ font-family:var(--text-font); line-height:1.5em } .entry-excerpt { display: block; font-size: 14px; color: #b5b5ba; margin: 5px 0 0; } .before-mask:before{ content:''; position:absolute; left:0; right:0; bottom:0; height:70%; background-image:linear-gradient(to bottom,rgba(0,0,0,0),rgba(0,0,0,0.7)); -webkit-backface-visibility:hidden; backface-visibility:hidden; z-index:2; opacity:1; margin:0; transition:opacity .25s ease } .card-style{ overflow:hidden }
.entry-info{ position:absolute; left:0; bottom:0; width:100%; background:linear-gradient(to bottom,rgba(0,0,0,0) 10%,rgba(0,0,0,0.5)); overflow:hidden; z-index:10; display:flex; flex-direction:column; padding:15px }
