b:if.b:template-skin:
html,body#layout #outer-wrapper,body#layout .row{
    width:auto;
    padding:0
}
 body#layout{
    position:relative;
    width:auto;
    max-width:100%;
    background-color:#f9f9f9;
    padding:95px 5px 0;
    margin:0
}
 body#layout:before{
    content:'Xapify - Version - 1.0';
    position:absolute;
    top:0;
    left:5px;
    right:5px;
    height:95px;
    font-family:Roboto,sans-serif;
    font-size:23px;
    color:#0F1618;
    line-height:95px;
    text-align:center
}
 body#layout div.section{
    display:block;
    background-color:#f1f1f1!important;
    margin:0 5px 10px!important;
    padding:16px 16px 18px!important;
    border-color:#e5e5e5
}
 body#layout .no-items.section{
    display:block
}
 body#layout .section h4{
    font-size:14px;
    color:#0F1618;
    text-transform:uppercase;
    margin:0
}
 body#layout .section h4:after{
    text-transform:initial;
    color:#656565;
    font-weight:400
}
 body#layout .add_widget a{
    color:#3c97ef!important
}
 body#layout .widget-wrap3{
    overflow:hidden
}
 body#layout .widget-content{
    width:auto;
    max-width:none;
    max-height:none;
    margin:0;
    border:1px solid #e5e5e5;
    border-left:0
}
 body#layout .locked-widget .widget-content{
    border-left:1px solid #3c97ef
}
 body#layout .locked-widget .widget-content:hover{
    border-left-color:#00b140
}
 body#layout .widget .widget-content a.editlink{
    border-radius:2px
}
 body#layout .visibility .editlink{
    background:#3c97ef url(https://1.bp.blogspot.com/-iQoCOwqjB-w/Wy1bDznOM4I/AAAAAAAACGA/8BUOPStr0sk5oud9hWpHBQTrmkeJDoAvACK4BGAYYCw/s18-c/mode_edit_w600_24dp.png) no-repeat center!important
}
 body#layout .visibility .editlink:hover{
    background-color:#00b140!important
}
 body#layout .draggable-widget .widget-wrap2{
    background:#3c97ef url(https://1.bp.blogspot.com/-yTAuT5aZ1EY/Wy1eEeo4SbI/AAAAAAAACGM/FxOTPwL-Ch0_lyZxLRzhv2EWHINOmCjWACK4BGAYYCw/s22/draggable.png) no-repeat 4px 50%!important
}
 body#layout .draggable-widget .widget-wrap1:hover .widget-wrap2{
    background-color:#00b140!important
}
 body#layout .visibility .layout-widget-state.visible{
    background-image:url(https://4.bp.blogspot.com/-qicweZaCb7I/XR_IGBqqGfI/AAAAAAAABS0/MIpI_COKj6MBkeN9FEJhqL96WYnYfGjngCK4BGAYYCw/s1600/visibility_c3_600_24dp.png)!important
}
 body#layout .visibility .layout-widget-state.not-visible{
    background-image:url(https://4.bp.blogspot.com/-tqL3-mrEM7A/XR_H_P3mFZI/AAAAAAAABSs/4PO1g3CDQbse_mJYzwn-60OQoYMFcq1FQCK4BGAYYCw/s1600/visibility_off_c3_600_24dp.png)!important;
    opacity:1
}
 body#layout div.layout-widget-description{
    display:none;
    font-size:11px;
    line-height:1.2em
}
 body#layout #theme-options,body#layout #main-menu .widget{
    display:block!important
}
 body#layout div.ify-panel{
    background-color:#edf4ff!important;
    overflow:hidden!important;
    border-color:#cdd4ef
}
 body#layout .ify-panel .widget{
    float:left;
    width:32.66%;
    margin-right:1%
}
 body#layout .ify-panel .widget-content{
    border-color:#cdd4ef!important
}
 body#layout .ify-panel .HTML{
    margin-right:0
}
 body#layout .ify-panel div.layout-widget-description,body#layout .flex-right,body#layout #nav-search-wrap{
    display:none
}
 body#layout .topbar-items,body#layout .flex-left{
    display:flex
}
 body#layout .topbar-menu,body#layout .topbar-social,body#layout .main-logo{
    width:100%
}
body#layout .topbar-items .flex-left, body#layout .topbar-items .flex-center, body#layout .topbar-items .flex-right {
display: flex;
    width: 33.33333333%;
}
body#layout .next-pro-main-nav{
    width:100%
}
 body#layout #content-wrapper{
    padding:0;
    margin:0
}
 body#layout #content-wrapper > .container{
    display:flex;
    margin:0
}
 body#layout #main-wrapper{
    width:67%;
    padding:0
}
 body#layout div.content-section.section,body#layout div.main-ads.section{
    background-color:#edf4ff!important;
    border-color:#d9dff3
}
 body#layout #sidebar-wrapper{
    width:33%;
    padding:0
}
 body#layout #custom-ads{
    display:flex
}
 body#layout #custom-ads .section{
    width:50%
}
 body#layout #next-pro-about-section{
    overflow:hidden!important
}
 body#layout #next-pro-about-section .widget{
    float:left;
    width:49.5%;
    margin-right:1%
}
 body#layout #next-pro-about-section .LinkList{
    margin-right:0
}
 body#layout .footerbar .container{
    display:flex
}
 body#layout #footer-menu,body#layout #footer-copyright{
    width:50%
}
 body#layout #next-pro-cookie-ify{
    margin:0 0 30px
}
 body#layout .section > h4:after{
    font-size:12px
}
 body#layout #ify-panel > h4:after{
    content:' - Custom No Image, Date Format, Month Names and More.'
}
 body#layout #topbar-menu > h4:after{
    content:' - Top Links'
}
 body#layout #topbar-social > h4:after{
    content:' - Social Icons'
}
 body#layout #main-logo > h4:after{
    content:' - Recommended Height (38px)'
}
body#layout #next-mobile-logo-section > h4:after{
    content:' - Recommended Height (34px)'
}
 body#layout #next-pro-main-nav > h4:after{
    content:' - With SubLinks and Mega Menu'
}
 body#layout #featured > h4:after{
    content:' - by Popular Posts, Most Recents or Label'
}
 body#layout #header-ads > h4:after{
    content:' - by Custom HTML, Adsense or Image'
}
 body#layout #home-ads > h4:after{
    content:' - by Custom HTML, Adsense or Image'
}
 body#layout .content-section > h4:after{
    content:' - by Most Recents or Label (Homepage)'
}
 body#layout .main-ads > h4:after{
    content:' - by Custom HTML, Adsense or Image (Homepage)'
}
 body#layout #main > h4:after{
    content:' - Default Blog Posts, AdSense In-Feed, Comments and More'
}
 body#layout #next-pro-main-before-ad > h4:after{
    content:' - Before Post Content (Post Page)'
}
 body#layout #next-pro-main-after-ad > h4:after{
    content:' - After Post Content (Post Page)'
}
 body#layout #next-pro-related-posts > h4:after{
    content:' - Advanced Related Posts (Post Page)'
}
 body#layout #next-pro-post-footer-ads > h4:after{
    content:' - After Related Posts (Post Page)'
}
 body#layout #sidebar > h4:after{
    content:' - on All Pages'
}
 body#layout #footer-ads > h4:after{
    content:' - by Custom HTML, Adsense or Image'
}
 body#layout #next-pro-about-section > h4:after{
    content:' - Site Logo, Description and Social Icons'
}
 body#layout #footer-copyright > h4:after{
    content:' - Custom Credits'
}
 body#layout #footer-menu > h4:after{
    content:' - Footer Links'
}
 body#layout #next-pro-cookie-ify-section > h4:after{
    content:' - Advanced Cookie Consent Plugin'
}
 body#layout #hidden-widgets, body#layout #hidden-widgets-side{
    display:none!important
}

